22	constexpr auto encode_addi(uint32_t rd, uint32_t rs1, uint32_t imm) -> uint32_t
23	{
24	  return (imm << 20) | (rs1 << 15) | (0u << 12) | (rd << 7) | 0x13u;
25	}
