171	TEST_CASE("csr_trigger: 2-byte stride skips compressed insns and aligns 4-byte insns")
172	{
173	  // Layout:
174	  //   0x80000000: c.addi x1, 1     (2 bytes, RVC: bits[1:0] != 0b11)
175	  //   0x80000002: csrwi 0x7C0, 1   (4 bytes)
176	  //   0x80000006: c.nop            (2 bytes)
177	  hybrid::CsrTrigger trig;
178	  alignas(uint32_t) std::array<uint8_t, 8> bytes{};
179	  // c.addi x1, 1 = 0x0085 (op=01, funct3=000, rd=x1, imm=1) -- rvc bits[1:0]=01
180	  // Use a placeholder 16-bit RVC pattern: 0x0085
181	  bytes[0] = 0x85;
182	  bytes[1] = 0x00;
183	  // csrwi 0x7C0, 1 = 0x7C00D073 (little-endian: 73 D0 00 7C)
184	  const uint32_t exit_insn = encode_csrrwi(0, 0x7C0, 1);
185	  std::memcpy(&bytes[2], &exit_insn, sizeof(exit_insn));
186	  // c.nop = 0x0001 (rvc bits[1:0]=01)
187	  bytes[6] = 0x01;
188	  bytes[7] = 0x00;
189	
190	  trig.scan_buffer(std::span<const uint8_t>{bytes.data(), bytes.size()},
191	                   /*base_pc=*/0x80000000);
192	
193	  // Only the 4-byte csrwi at 0x80000002 should match.
194	  CHECK_FALSE(trig.lookup(0x80000000).has_value());
195	  REQUIRE(trig.lookup(0x80000002));
196	  CHECK(trig.lookup(0x80000002)->kind == HYBRID_HANDOFF_EXIT);
197	  CHECK_FALSE(trig.lookup(0x80000006).has_value());
198	}
